    result = [[6]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            # Check which quadrant this cell is in
            if i < n/2 and j < n/2:
                result[i][j] = 7
            elif i < n/2 and j >= n/2:
                result[i][j] = 6
            elif i >= n/2 and j < n/2:
                result[i][j] = 6
