# Try: 6x6 with 7s forming a centered diamond
def diamond_pattern(n, center_val=7, bg_val=6):
    center = n // 2
    result = [[bg_val]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            dist = abs(i - center) + abs(j - center)
            if dist <= center:
                result[i][j] = center_val
    return result

